 static class SafehouseTransferTests {
  static Type api;static int checks;
  static void Check(bool value,string message){checks++;if(!value)throw new Exception("FAIL: "+message);}
  static Dictionary<string,object> D(object value){var json=new JavaScriptSerializer{MaxJsonLength=int.MaxValue};return json.Deserialize<Dictionary<string,object>>(json.Serialize(value));}
  static string[] Strings(Dictionary<string,object> value,string key){return ((IEnumerable)value[key]).Cast<object>().Select(Convert.ToString).ToArray();}
  static object Call(object service,string method,params object[] arguments){try{return api.GetMethod(method).Invoke(service,arguments);}catch(TargetInvocationException error){System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(error.InnerException).Throw();throw;}}
  static Exception Refuses(Action work,string message){try{work();}catch(Exception error){Check(true,message);return error;}throw new Exception("FAIL: "+message);}
  static void Put(string file,string text){Directory.CreateDirectory(Path.GetDirectoryName(file));File.WriteAllText(file,text,new UTF8Encoding(false));}
  static void Bytes(string file,byte[] bytes){Directory.CreateDirectory(Path.GetDirectoryName(file));File.WriteAllBytes(file,bytes);}
  static string Mods(params string[] ids){return "VERSION = 1,\nmods\n{\n"+string.Concat(ids.Select(id=>" mod = "+id+",\n"))+"}\nmaps\n{\n map = Muldraugh, KY,\n}\n";}
  sealed class Fixture {
   internal readonly string Root,SourceId="Sandbox/来源 房屋",TargetId="Sandbox/目标 世界",Source,Target;internal readonly Engine E;internal readonly object Service;internal readonly byte[] SourceBytes,TargetBytes,DictionaryBytes;
   internal Fixture(){Root=Path.Combine(Path.GetTempPath(),"ozl-house-"+Guid.NewGuid().ToString("N"));E=new Engine(Path.Combine(Root,"Game"),Path.Combine(Root,"User"),Path.Combine(Root,"Data"),true,null,name=>new Process[0]);Put(E.Config,"{\"vmArgs\":[]}");Put(Path.Combine(E.Game,"game-version.txt"),"42.20.3");Directory.CreateDirectory(E.Data);Source=Path.Combine(E.User,"Saves","Sandbox","来源 房屋");Target=Path.Combine(E.User,"Saves","Sandbox","目标 世界");Put(Path.Combine(Source,"mods.txt"),Mods("A","B","Missing"));Put(Path.Combine(Target,"mods.txt"),Mods("B","A"));Put(E.Mods,Mods("Global"));Bytes(Path.Combine(Source,"WorldDictionary.bin"),SafehouseTransferFormatTests.DictionaryFixture(new short[]{1,2},new[]{"Base.Apple","Mod.Missing"}));DictionaryBytes=SafehouseTransferFormatTests.DictionaryFixture(new short[]{7},new[]{"Base.Apple"});Bytes(Path.Combine(Target,"WorldDictionary.bin"),DictionaryBytes);SourceBytes=SafehouseTransferFormatTests.ChunkFixture(new short[]{1,2},new[]{3,2});TargetBytes=SafehouseTransferFormatTests.ChunkFixture(new short[]{7},new[]{1});Bytes(Path.Combine(Source,"map","10","20.bin"),SourceBytes);Bytes(Path.Combine(Source,"map","9","19.bin"),SafehouseTransferFormatTests.ChunkFixture(new short[]{1},new[]{1}));Bytes(Path.Combine(Source,"map","-1","-1.bin"),SafehouseTransferFormatTests.ChunkFixture(new short[]{1},new[]{1}));Bytes(Path.Combine(Target,"map","10","20.bin"),TargetBytes);Put(Path.Combine(Target,"players.db"),"keep target players");Put(Path.Combine(Target,"vehicles.db"),"keep target vehicles");Put(Path.Combine(Target,"map_meta.bin"),"keep target global metadata");Put(Path.Combine(Target,"isoregiondata","datachunk_10_20.bin"),"old center cache");Put(Path.Combine(Target,"isoregiondata","datachunk_9_19.bin"),"old neighboring cache");Put(Path.Combine(Target,"isoregiondata","datachunk_99_99.bin"),"unrelated cache");using(var header=new MemoryStream()){SafehouseTransferFormatTests.Int(header,195);SafehouseTransferFormatTests.Int(header,3);SafehouseTransferFormatTests.Int(header,RegionHash(10,20));SafehouseTransferFormatTests.Int(header,RegionHash(9,19));SafehouseTransferFormatTests.Int(header,RegionHash(99,99));Bytes(Path.Combine(Target,"isoregiondata","RegionHeader.bin"),header.ToArray());}Service=Activator.CreateInstance(api,BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance,null,new object[]{E},null);}
   internal Dictionary<string,object> Preview(int margin=0){return D(Call(Service,"Preview",SourceId,TargetId,81,161,82,162,margin,CancellationToken.None));}
   internal Dictionary<string,object> Apply(Dictionary<string,object> preview,CancellationToken cancellation){return D(Call(Service,"Apply",(string)preview["previewStamp"],true,cancellation));}
