   internal void Preserved(){Check(File.ReadAllText(Path.Combine(Target,"players.db"))=="keep target players"&&File.ReadAllText(Path.Combine(Target,"vehicles.db"))=="keep target vehicles"&&File.ReadAllText(Path.Combine(Target,"map_meta.bin"))=="keep target global metadata","transfer preserves destination characters vehicles and global metadata");Check(File.ReadAllBytes(Path.Combine(Target,"WorldDictionary.bin")).SequenceEqual(DictionaryBytes)&&File.ReadAllText(Path.Combine(Target,"mods.txt"))==Mods("B","A")&&File.ReadAllText(E.Mods)==Mods("Global"),"destination dictionary and source/destination/default mod lists are not replaced");}
  }
  static int RegionHash(int x,int y){return unchecked((y<<16)^x);}
  static Dictionary<string,byte[]> Snapshot(string root){return Directory.GetFiles(root,"*",SearchOption.AllDirectories).ToDictionary(path=>path,path=>File.ReadAllBytes(path));}
  static bool SameSnapshot(Dictionary<string,byte[]> before,string root){return before.Count==Directory.GetFiles(root,"*",SearchOption.AllDirectories).Length&&before.All(item=>File.Exists(item.Key)&&File.ReadAllBytes(item.Key).SequenceEqual(item.Value));}
  public static int Main(){try{Run();return 0;}catch(Exception error){Console.WriteLine(error);return 1;}}
  public static void Run(){api=typeof(Engine).Assembly.GetType("PZ3D.SafehouseTransfer");Check(api!=null,"native transactional house transfer service exists");IdentityUnknownCount();PreviewAndApply();BoundsAndExclusions();StaleInputs();Unsupported();CancellationAndRollback();LifecycleAndRaces();Junctions();Running();Console.WriteLine("SafehouseTransfer PASS: "+checks+" assertions; isolated fixtures only");}
  static void IdentityUnknownCount(){
   // Catches treating an incomplete heuristic census as zero while safely copying identity-mapped chunk bytes.
   var known=new Fixture();var knownPreview=known.Preview();Check(knownPreview.ContainsKey("itemCountKnown")&&Convert.ToBoolean(knownPreview["itemCountKnown"]),"complete recognized item census is explicitly known");
   var f=new Fixture();byte[] dictionary=SafehouseTransferFormatTests.DictionaryFixture(new short[]{1,2},new[]{"Base.Apple","Base.PipeBomb"}),opaque=SafehouseTransferFormatTests.TrapWithWeapon();Bytes(Path.Combine(f.Source,"WorldDictionary.bin"),dictionary);Bytes(Path.Combine(f.Target,"WorldDictionary.bin"),dictionary);Bytes(Path.Combine(f.Source,"map","10","20.bin"),opaque);Bytes(Path.Combine(f.Target,"map","10","20.bin"),SafehouseTransferFormatTests.ChunkFixture(new short[]{1},new[]{1}));var targetBefore=Snapshot(f.Target);var sourceBefore=Snapshot(f.Source);var preview=f.Preview(1);Check(Convert.ToBoolean(preview["canTransfer"])&&!Convert.ToBoolean(preview["itemCountKnown"])&&Convert.ToInt32(preview["chunkCount"])==2,"one unknown identity census marks the entire mixed known/unknown region quantity unknown");Check(Convert.ToInt64(preview["itemCount"])==-1&&Convert.ToInt64(preview["itemsTransferred"])==-1&&Convert.ToInt64(preview["itemsRemoved"])==0,"unknown identity quantity is never reported as zero or as the recognized subset");var result=f.Apply(preview,CancellationToken.None);Check((string)result["status"]=="completed"&&!Convert.ToBoolean(result["itemCountKnown"])&&Convert.ToInt64(result["itemsTransferred"])==-1&&((string)result["message"]).Contains("未统计"),"completed identity transfer reports copied chunks with an honest unknown item quantity");Check(File.ReadAllBytes(Path.Combine(f.Target,"map","10","20.bin")).SequenceEqual(opaque)&&SameSnapshot(sourceBefore,f.Source),"identity fallback copies the complete opaque trap chunk byte-exact and preserves source");SaveBackups.Restore(f.E,f.TargetId,(string)result["recoveryId"],true,CancellationToken.None);Check(SameSnapshot(targetBefore,f.Target),"protected full recovery exactly undoes unknown-census identity transfer");
  }
  static void PreviewAndApply(){
   // Catches live-save mutation in preview, incorrect quantity counts, destructive global-file replacement and missing undo snapshots.
   var f=new Fixture();var before=Snapshot(f.Root);var preview=f.Preview();Check(Convert.ToBoolean(preview["canTransfer"])&&Convert.ToInt32(preview["chunkCount"])==1&&Convert.ToInt32(preview["overwrittenChunks"])==1&&Convert.ToInt32(preview["addedChunks"])==0,"preview identifies the exact same-coordinate chunk replacement");var actual=D(preview["actualBounds"]);Check(Convert.ToInt32(actual["minX"])==80&&Convert.ToInt32(actual["minY"])==160&&Convert.ToInt32(actual["maxX"])==87&&Convert.ToInt32(actual["maxY"])==167,"preview expands tile rectangle to complete 8 by 8 chunk extent");Check(Strings(preview,"sourceMods").SequenceEqual(new[]{"A","B","Missing"})&&Strings(preview,"targetMods").SequenceEqual(new[]{"B","A"})&&Strings(preview,"sourceOnlyMods").SequenceEqual(new[]{"Missing"})&&((IEnumerable)preview["orderChanges"]).Cast<object>().Count()==2,"ordered source and target mod differences are previewed rather than automatically changed");Check(Convert.ToInt64(preview["itemCount"])==5&&Convert.ToInt64(preview["itemsTransferred"])==3&&Convert.ToInt64(preview["itemsRemoved"])==2&&Strings(preview,"missingTypes").SequenceEqual(new[]{"Mod.Missing"}),"preview counts actual item quantities and approved missing-type removals");Check(SameSnapshot(before,f.Root),"preview performs no persistent writes anywhere in fixture");Refuses(()=>Call(f.Service,"Apply",preview["previewStamp"],false,CancellationToken.None),"apply requires explicit current-preview confirmation");Check(SameSnapshot(before,f.Root),"unconfirmed apply creates neither snapshot nor save mutations");var sourceBefore=Snapshot(f.Source);var result=f.Apply(preview,CancellationToken.None);Check((string)result["status"]=="completed"&&Convert.ToInt64(result["itemsRemoved"])==2&&Convert.ToInt64(result["itemsTransferred"])==3,"successful result reports genuine chunk and item work");Check(File.ReadAllBytes(Path.Combine(f.Target,"map","10","20.bin")).SequenceEqual(SafehouseTransferFormatTests.ChunkFixture(new short[]{7,-1},new[]{3,2})),"target chunk contains remapped IDs and null-removal sentinel with valid CRC");Check(SameSnapshot(sourceBefore,f.Source),"source world remains byte-for-byte unchanged");Check(!File.Exists(Path.Combine(f.Target,"isoregiondata","datachunk_10_20.bin"))&&!File.Exists(Path.Combine(f.Target,"isoregiondata","datachunk_9_19.bin"))&&File.ReadAllText(Path.Combine(f.Target,"isoregiondata","datachunk_99_99.bin"))=="unrelated cache","only related IsoRegion caches and one-ring neighbors are invalidated");byte[] header=File.ReadAllBytes(Path.Combine(f.Target,"isoregiondata","RegionHeader.bin"));Check(header.Length==12&&header[7]==1&&header.Skip(8).SequenceEqual(new byte[]{0,99,0,99}),"RegionHeader retains unrelated region hash with exact valid count");f.Preserved();string recovery=(string)result["recoveryId"];Check(f.Archives().Any(row=>(string)row["id"]==recovery&&Convert.ToBoolean(row["recovery"])),"destination has a real full protected pre-transfer backup");Refuses(()=>f.Apply(preview,CancellationToken.None),"successful transfer consumes its native-issued preview receipt");SaveBackups.Restore(f.E,f.TargetId,recovery,true,CancellationToken.None);Check(File.ReadAllBytes(Path.Combine(f.Target,"map","10","20.bin")).SequenceEqual(f.TargetBytes)&&File.ReadAllText(Path.Combine(f.Target,"isoregiondata","datachunk_10_20.bin"))=="old center cache","existing full backup restore exactly undoes chunk and cache migration");f.Preserved();
  }
  static void BoundsAndExclusions(){
   var f=new Fixture();var margin=f.Preview(1);Check(Convert.ToBoolean(margin["canTransfer"])&&Convert.ToInt32(margin["chunkCount"])==2&&Convert.ToInt64(margin["missingChunks"])==7,"explicit one-chunk margin includes present source chunks and counts missing holes");var bounds=D(margin["actualBounds"]);Check(Convert.ToInt32(bounds["minX"])==72&&Convert.ToInt32(bounds["maxX"])==95&&Convert.ToInt32(bounds["minY"])==152&&Convert.ToInt32(bounds["maxY"])==175,"margin is reflected in overwrite extent before confirmation");var negative=D(Call(f.Service,"Preview",f.SourceId,f.TargetId,-1,-1,-1,-1,0,CancellationToken.None));bounds=D(negative["actualBounds"]);Check(Convert.ToBoolean(negative["canTransfer"])&&Convert.ToInt32(bounds["minX"])==-8&&Convert.ToInt32(bounds["maxX"])==-1,"negative tile coordinates use floor division rather than truncation");Check(!Convert.ToBoolean(D(Call(f.Service,"Preview",f.SourceId,f.SourceId,80,160,87,167,0,CancellationToken.None))["canTransfer"]),"source and target cannot be the same physical save");Check(!Convert.ToBoolean(D(Call(f.Service,"Preview",f.SourceId,"Multiplayer/Server",80,160,87,167,0,CancellationToken.None))["canTransfer"]),"multiplayer caches cannot be a transfer destination");Refuses(()=>Call(f.Service,"Apply","housePreview:"+Guid.NewGuid().ToString("N"),true,CancellationToken.None),"unissued preview receipt cannot authorize writes");Check(f.Archives().Length==0,"all region previews and refusals leave archive history untouched");
  }
  static void StaleInputs(){
   // Catches stale receipts being accepted after source chunks, target chunks, dictionaries or mod order change.
   foreach(string changed in new[]{"source","target","mods","dictionary"}){var f=new Fixture();var preview=f.Preview();if(changed=="source")Bytes(Path.Combine(f.Source,"map","10","20.bin"),SafehouseTransferFormatTests.ChunkFixture(new short[]{1},new[]{4}));if(changed=="target")Bytes(Path.Combine(f.Target,"map","10","20.bin"),SafehouseTransferFormatTests.ChunkFixture(new short[]{7},new[]{4}));if(changed=="mods")Put(Path.Combine(f.Target,"mods.txt"),Mods("A","B"));if(changed=="dictionary")Bytes(Path.Combine(f.Target,"WorldDictionary.bin"),SafehouseTransferFormatTests.DictionaryFixture(new short[]{8},new[]{"Base.Apple"}));var before=Snapshot(f.Target);Refuses(()=>f.Apply(preview,CancellationToken.None),"changed "+changed+" invalidates issued preview");Check(SameSnapshot(before,f.Target)&&f.Archives().Length==0,"stale "+changed+" refusal writes neither destination nor backup");}
  }
  static void Unsupported(){
   foreach(string reason in new[]{"crc","world","dictionary","header","weapon-attachment"}){var f=new Fixture();if(reason=="crc"){var bytes=(byte[])f.SourceBytes.Clone();bytes[bytes.Length-1]^=1;Bytes(Path.Combine(f.Source,"map","10","20.bin"),bytes);}if(reason=="world")Bytes(Path.Combine(f.Source,"map","10","20.bin"),SafehouseTransferFormatTests.Wrap(new byte[0],247));if(reason=="dictionary")Bytes(Path.Combine(f.Target,"WorldDictionary.bin"),SafehouseTransferFormatTests.DictionaryFixture(new short[]{7},new[]{"Base.Apple"},true));if(reason=="header")Bytes(Path.Combine(f.Target,"isoregiondata","RegionHeader.bin"),new byte[]{1,2});if(reason=="weapon-attachment")Bytes(Path.Combine(f.Source,"map","10","20.bin"),SafehouseTransferFormatTests.WeaponWithPart());var before=Snapshot(f.Root);var preview=f.Preview();Check(!Convert.ToBoolean(preview["canTransfer"])&&Strings(preview,"errors").Length>0,"unsupported "+reason+" is explicitly unavailable during preview");Check(SameSnapshot(before,f.Root),"unsupported "+reason+" cannot mutate worlds or create backups");}
  }
  static void CancellationAndRollback(){
   var f=new Fixture();var preview=f.Preview();var before=Snapshot(f.Target);using(var cancellation=new CancellationTokenSource()){f.E.Progress=(p,text)=>{if(text.Contains("复制目标存档"))cancellation.Cancel();};Check(Refuses(()=>f.Apply(preview,cancellation.Token),"cancellation during full destination staging refuses") is OperationCanceledException,"cancelled transfer keeps cancellation identity");}Check(SameSnapshot(before,f.Target)&&f.Archives().Any(row=>Convert.ToBoolean(row["recovery"])),"cancelled staging retains exact original target and protected recovery snapshot");
   var race=new Fixture();preview=race.Preview();before=Snapshot(race.Target);bool changed=false;race.E.Progress=(p,text)=>{if(!changed&&text.Contains("验证迁移暂存")){changed=true;string stage=Directory.GetDirectories(Path.Combine(race.E.User,".orange-world-edits"),"stage",SearchOption.AllDirectories).Single();Put(Path.Combine(stage,"players.db"),"unapproved stage mutation");}};Refuses(()=>race.Apply(preview,CancellationToken.None),"unapproved stage mutation invalidates publication");Check(changed&&SameSnapshot(before,race.Target),"mutated staged global file never replaces target");
   var rollback=new Fixture();preview=rollback.Preview();before=Snapshot(rollback.Target);FileStream held=null;bool moved=false;rollback.E.Progress=(p,text)=>{if(text.Contains("正在替换存档目录")){moved=!Directory.Exists(rollback.Target);string stage=Directory.GetDirectories(Path.Combine(rollback.E.User,".orange-world-edits"),"stage",SearchOption.AllDirectories).Single();held=new FileStream(Path.Combine(stage,"map","10","20.bin"),FileMode.Open,FileAccess.Read,FileShare.Read);}};try{Refuses(()=>rollback.Apply(preview,CancellationToken.None),"second directory rename failure invokes rollback");}finally{if(held!=null)held.Dispose();}Check(moved&&SameSnapshot(before,rollback.Target),"failed second rename restores the displaced complete original destination");
  }
  static void Junctions(){
   var f=new Fixture();string outside=Path.Combine(f.Root,"outside");Directory.CreateDirectory(outside);Bytes(Path.Combine(outside,"20.bin"),f.SourceBytes);Directory.Move(Path.Combine(f.Source,"map","10"),Path.Combine(f.Source,"map","10-old"));Junction(Path.Combine(f.Source,"map","10"),outside);var preview=f.Preview();Check(!Convert.ToBoolean(preview["canTransfer"])&&f.Archives().Length==0&&File.ReadAllBytes(Path.Combine(outside,"20.bin")).SequenceEqual(f.SourceBytes),"source junction is refused without traversing or changing foreign data");
  }
  static void LifecycleAndRaces(){
   // Catches changed sources between analysis and publication, stale disposed controllers and cancellation after a committed rename.
   var sourceRace=new Fixture();var preview=sourceRace.Preview();var targetBefore=Snapshot(sourceRace.Target);bool changed=false;sourceRace.E.Progress=(p,text)=>{if(!changed&&text.Contains("迁移区块")){changed=true;Bytes(Path.Combine(sourceRace.Source,"map","10","20.bin"),SafehouseTransferFormatTests.ChunkFixture(new short[]{1},new[]{9}));}};Refuses(()=>sourceRace.Apply(preview,CancellationToken.None),"source mutation during staged patches invalidates publication");Check(changed&&SameSnapshot(targetBefore,sourceRace.Target),"source race leaves original destination untouched");
   var disposed=new Fixture();preview=disposed.Preview();((IDisposable)disposed.Service).Dispose();Refuses(()=>disposed.Apply(preview,CancellationToken.None),"disposed selected-engine service cannot apply an old receipt");Check(disposed.Archives().Length==0,"disposed receipt cannot create a backup or write the destination");
   var waiting=new Fixture();preview=waiting.Preview();Exception error=null;Thread worker;using(var cancellation=new CancellationTokenSource())using(var entered=new ManualResetEventSlim()){using(PlayProfileTransaction.Lock(waiting.E)){worker=new Thread(()=>{entered.Set();try{waiting.Apply(preview,cancellation.Token);}catch(Exception failure){error=failure;}});worker.Start();Check(entered.Wait(3000)&&SpinWait.SpinUntil(()=>(worker.ThreadState&System.Threading.ThreadState.WaitSleepJoin)!=0,3000),"apply waits for the shared launch/profile lease");cancellation.Cancel();}worker.Join();Check(error is OperationCanceledException&&waiting.Archives().Length==0,"cancellation during lease wait prevents all backup and world writes");}
   var committed=new Fixture();preview=committed.Preview();using(var cancellation=new CancellationTokenSource()){committed.E.Progress=(p,text)=>{if(p==100&&text.Contains("房屋区域迁移已完成"))cancellation.Cancel();};var result=committed.Apply(preview,cancellation.Token);Check((string)result["status"]=="completed"&&File.ReadAllBytes(Path.Combine(committed.Target,"map","10","20.bin")).SequenceEqual(SafehouseTransferFormatTests.ChunkFixture(new short[]{7,-1},new[]{3,2})),"cancellation after atomic publication does not falsely report a completed transfer as cancelled");}
   var journal=new Fixture();preview=journal.Preview();string operation=null;journal.E.Progress=(p,text)=>{if(text.Contains("正在替换存档目录")){operation=Directory.GetDirectories(Path.Combine(journal.E.User,".orange-world-edits")).Single();string owner=Path.Combine(operation,"owner.json");File.SetAttributes(owner,File.GetAttributes(owner)|FileAttributes.ReadOnly);}};var recorded=journal.Apply(preview,CancellationToken.None);Check((string)recorded["status"]=="completed"&&Directory.Exists(Path.Combine(operation,"displaced")),"post-commit journal failure preserves old directory and reports the actual successful publication");Check(!((IEnumerable)D(SaveProfiles.List(journal.E))["saves"]).Cast<object>().Select(D).Any(row=>((string)row["id"]).Contains("stage")||((string)row["id"]).Contains("displaced")),"retained edit transaction directories are never exposed as launchable worlds");
   var observer=new Fixture();preview=observer.Preview();observer.E.Progress=(p,text)=>{if(p==100&&text.Contains("房屋区域迁移已完成"))throw new IOException("closed progress observer");};var completed=observer.Apply(preview,CancellationToken.None);Check((string)completed["status"]=="completed","a closed progress observer cannot turn an already committed transfer into a reported failure");
  }
  static void Running(){
   var f=new Fixture();string image=Process.GetCurrentProcess().MainModule.FileName;Check(Path.GetFileName(image)=="ProjectZomboid64.exe","running check uses only its own synthetic test executable");var running=new Engine(Path.GetDirectoryName(image),f.E.User,f.E.Data,true,null,name=>name=="ProjectZomboid64"?new[]{Process.GetCurrentProcess()}:new Process[0]);Put(running.Config,"{\"vmArgs\":[]}");object service=Activator.CreateInstance(api,BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance,null,new object[]{running},null);var preview=D(Call(service,"Preview",f.SourceId,f.TargetId,80,160,87,167,0,CancellationToken.None));Check(!Convert.ToBoolean(preview["canTransfer"])&&Strings(preview,"errors").Any(),"real matching running-process identity blocks preview eligibility");f.Preserved();
  }
