  static void Junction(string link,string target){Directory.CreateDirectory(link);byte[] sub=Encoding.Unicode.GetBytes("\\??\\"+target),print=Encoding.Unicode.GetBytes(target),buffer=new byte[20+sub.Length+print.Length];Array.Copy(BitConverter.GetBytes(0xA0000003U),buffer,4);Array.Copy(BitConverter.GetBytes((ushort)(buffer.Length-8)),0,buffer,4,2);Array.Copy(BitConverter.GetBytes((ushort)sub.Length),0,buffer,10,2);Array.Copy(BitConverter.GetBytes((ushort)(sub.Length+2)),0,buffer,12,2);Array.Copy(BitConverter.GetBytes((ushort)print.Length),0,buffer,14,2);Array.Copy(sub,0,buffer,16,sub.Length);Array.Copy(print,0,buffer,18+sub.Length,print.Length);using(var handle=CreateFile(link,0x40000000,3,IntPtr.Zero,3,0x02200000,IntPtr.Zero)){int returned;Check(!handle.IsInvalid&&DeviceIoControl(handle,0x000900A4,buffer,buffer.Length,IntPtr.Zero,0,out returned,IntPtr.Zero),"isolated junction fixture created without launching process");}}
